def solve(nums, target):
    first = -1
    last = -1
    left = 0
    right = len(nums) - 1

    # Find the first occurrence
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            first = mid
            right = mid - 1  # Look for earlier occurrences

    # Find the last occurrence
    left = 0
    right = len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            last = mid
            left = mid + 1  # Look for later occurrences

    return [first, last]
