    first = -1
    last = -1
    n = len(nums)

    # Find the first occurrence
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            first = mid
            right = mid - 1  # Look for earlier occurrences

    # Find the last occurrence
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            last = mid
            left = mid + 1  # Look for later occurrences

    return [first, last]
